# -*- coding: utf-8 -*-
# Numeric key-vs-statement review 25.09, part 1: decisions by hand, each re-verified numerically by verify_fix.py
# (the statement as it will be shown must equal the key as it will be stored).
KW = "ключ не совпадал с выражением из условия (численная проверка, пересчитано вручную): "
SH = "ключи подпунктов были перепутаны местами; ключ пересчитан по условию подпункта: "
QG = "в условии была искажена запись, ключ верен для восстановленного условия: "
P = {}
def K(t, k, note): P[t] = {"k": k, "why": KW + note}
def S(t, k, note): P[t] = {"k": k, "why": SH + note}
def Q(t, a, b, note, k=None):
    P[t] = {"qrep": (a, b), "why": QG + note}
    if k: P[t]["k"] = k
def QF(t, q, note): P[t] = {"q": q, "why": QG + note}

K("DIFF_G7_S08_02_C_03", r"$\dfrac{9}{2^{n}}$", "(2ⁿ·3ⁿ⁺¹)²·(1/6)ⁿ·(1/12)ⁿ = 2²ⁿ·3²ⁿ⁺²/(2³ⁿ·3²ⁿ) = 9/2ⁿ; прежний ключ 9 не зависел от n")
K("G10_TB_§21_21_4_5", r"$\dfrac{\sqrt{3}}{3}$", "числитель cos(64° − 4°) = cos 60°, знаменатель sin(19° + 41°) = sin 60°, частное ctg 60° = √3/3 (было 1)")
K("G10_TB_§25_25_4_2", r"$\dfrac{1}{2}$", "2sin(α/2 − π/12)cos(α/2 + π/12) = sin α − sin(π/6), значит выражение равно 1/2 (было 1/2 − cos α; условие совпадает с учебником Мерзляк 10, № 25.4 (2))")
K("G10_TB_§9_9_8_5", r"$\sqrt[3]{4}$", "⁹√64 = 2^{6/9} = ∛4 (было ∛2)")
K("G11_TB_16_3*_16_36_2", r"$\dfrac{4}{13}$", "сумма сопряжённых дробей = 2·Re((3 + 2i)(12 + 5i))/169 = 2·26/169 = 4/13 (было 62/169)")
K("G5_TB_34_1315.3", r"$54{,}4$", "14·2,3 + 6·3,7 = 32,2 + 22,2 = 54,4 (было 54,6)")
K("G5_TB_44_1746.1", r"$122{,}6$", "8·(1,4 + 13,6) + 13·(0,8 − 0,6) = 120 + 2,6 = 122,6 (было 122)")
K("G5_TB_59_1407", r"$109$", "(59·13 + 8688) : 31 − 196 = 9455 : 31 − 196 = 305 − 196 = 109 (было 108)")
K("G5_TB_64_1519.1", r"$18{,}218$", "29,48 − 18,48·0,65 + 0,75 = 29,48 − 12,012 + 0,75 = 18,218 (было 18,212)")
K("G6_TB_28_1108.2", r"$32{,}02$", "50,2 − 3,04·9,5 + 10,7 = 50,2 − 28,88 + 10,7 = 32,02 (было 32)")
K("G6_TB_14_596.9", r"$10$", "8 : 4/5 = 10 (было 0.4)")
K("G6_TB_16_674.9", r"$9$", "6 : 2/3 = 9 (было 1)")
K("G6_TB_30_1151.5", r"$-\dfrac{5}{6}$", "−5/8 : 3/4 = −5/6 (было −5/96)")
K("G6_TB_30_1151.9", r"$-7$", "−5 : 5/7 = −7 (было −1/7)")
K("G6_TB_30_1152.6", r"$11{,}5$", "(−21 + (−2)) : (−2) = 11,5 (было −20)")
K("G6_TB_34_1237.10", r"$3\dfrac{4}{7}$", "4 2/5 − 2/5 − 3/7 = 3 4/7 (было 3/4; условие совпадает с учебником Виленкин 6, № 1237 к))")
K("G6_TB_34_1237.12", r"$1\dfrac{2}{3}$", "3,15 + 2/3 − 2,15 = 1 2/3 (было 1/3)")
K("G6_TB_34_1238.2", r"$6\dfrac{1}{7} - x$", "(6 − x) + 1/7 = 6 1/7 − x (было 6/7 − x)")
K("G6_TB_34_1254.4", r"$1\dfrac{6}{7}$", "2 3/7 − 1 4/7 + 1 5/9 − 5/9 = 6/7 + 1 = 1 6/7 (было 1/6; условие совпадает с учебником Виленкин 6, № 1254 г))")
K("G7_ALG_10_13.1", r"$-0{,}1$", "−200·(−1/2)·(−0,1)³ = −200·0,0005 = −0,1 (было 0,1)")
K("G7_ALG_10_8.1", r"$2{,}5$", "12·1,75 − 7,25 − 11,25 = 2,5 (было 3)")
