K("G7_ALG_22_2.6", r"$1$", "(4 − 1)/(1 + 2) = 1 (было 1,5)")
K("G7_ALG_23_14.4", r"$\dfrac{7(c+d)}{c-d}$", "ключ был записан как «7 (c+d)/(c−d)» — читается как смешанное число; значение то же")
K("G10_TB_§24_24_6_1", r"$2\sin 30^{\circ}\cos 5^{\circ}$", "sin 25° + cos 55° = sin 25° + sin 35° = 2 sin 30° cos 5° (было 2 sin 55° cos 30° = sin 25° + sin 85°; условие совпадает с учебником Мерзляк 10, № 24.6 (1))")
K("G10_TB_§24_24_6_2", r"$2\sin 23^{\circ}\sin 1^{\circ}$", "cos 22° − sin 66° = cos 22° − cos 24° = 2 sin 23° sin 1° (было 2 sin 22° sin 44° = cos 22° − cos 66°; условие совпадает с учебником Мерзляк 10, № 24.6 (2))")
for t, k, n in [("G5_TB_38_1483.2", "0{,}407", "1,4245 : 3,5"), ("G5_TB_38_1483.3", "1{,}24", "0,02976 : 0,024"), ("G5_TB_38_1483.4", "0{,}34", "1,598 : 4,7"),
                ("G5_TB_38_1483.6", "3{,}8", "11,59 : 3,05"), ("G5_TB_38_1483.7", "5{,}02", "39,156 : 7,8"), ("G5_TB_38_1483.8", "0{,}25", "0,045 : 0,18"),
                ("G5_TB_38_1511.2", "1000", "100 : 0,1"), ("G5_TB_38_1511.3", "0{,}3", "0,18 : 0,6"), ("G5_TB_38_1511.4", "4", "0,8 : 0,2"),
                ("G5_TB_38_1511.6", "10", "0,1 : 0,01"), ("G5_TB_38_1511.7", "40", "20 : 0,5"), ("G5_TB_38_1511.8", "20", "6 : 0,3"),
                ("G5_TB_38_1516.2", "0{,}8", "1,872 : 2,34"), ("G5_TB_38_1516.3", "1{,}22", "41,48 : 34"), ("G5_TB_38_1516.4", "2{,}3", "0,8625 : 0,375"),
                ("G5_TB_38_1516.5", "13", "0,481 : 0,037")]:
    S(t, "$" + k + "$", n + " = " + k.replace("{,}", ","))
